// src/rename/rename.ts
async function renameAst(ast, options) {
  const started = performance.now();
  assertNoDynamicNameResolution(ast);
  const before = print(ast);
  const units = collectUnits(ast);
  const cache2 = new Map;
  const report = {
    units: units.length,
    cacheHits: 0,
    renamed: 0,
    skipped: 0,
    failures: [],
    astIdentical: true,
    ms: 0
  };
  const concurrency = options.concurrency ?? 8;
  if (!Number.isSafeInteger(concurrency) || concurrency < 1) {
    throw new RangeError("rename concurrency must be a positive integer");
  }
  const registry2 = new NameRegistry;
  let done = 0;
  for (let depthStart = 0;depthStart < units.length; ) {
    const depth = units[depthStart].depth;
    let depthEnd = depthStart + 1;
    while (depthEnd < units.length && units[depthEnd].depth === depth)
      depthEnd++;
    for (let i = depthStart;i < depthEnd; i += concurrency) {
      const window2 = units.slice(i, Math.min(i + concurrency, depthEnd)).map(refreshUnit);
      const proposals = await Promise.all(window2.map((unit) => {
        const cached = cache2.get(unit.hash);
        if (cached) {
          report.cacheHits++;
          return cached;
        }
        const request = (async () => {
          try {
            return await options.provider.propose(unit);
          } catch (err) {
            report.failures.push(`${unit.id}: ${err.message}`);
            return {};
          }
        })();
        cache2.set(unit.hash, request);
        return request;
      }));
      window2.forEach((unit, k) => {
        report.renamed += applyMapping(unit, proposals[k], report, registry2);
        options.onProgress?.(++done, units.length, unit);
      });
    }
    depthStart = depthEnd;
  }
  const after = print(ast);
  const equiv = compareAst(parse3(before), parse3(after), { alphaEquivalent: true });
  report.astIdentical = equiv.equal;
  if (!equiv.equal) {
    report.astDivergence = `${equiv.path}: ${equiv.reason} (${equiv.left} vs ${equiv.right})`;
    ast.program = parse3(before).program;
    report.renamed = 0;
  }
  report.ms = performance.now() - started;
  return report;
}
function applyMapping(unit, mapping, report, registry2) {
  let count = 0;
  for (const [oldName, proposed] of Object.entries(mapping)) {
    const binding = unit.scope.bindings[oldName];
    if (!binding) {
      report.skipped++;
      continue;
    }
    if (!isValidIdentifier2(proposed)) {
      report.skipped++;
      continue;
    }
    const finalName = deconflict(unit, binding, proposed, registry2);
    try {
      unit.scope.rename(oldName, finalName);
      registry2.claim(finalName, unit.scope);
      count++;
    } catch (err) {
      report.failures.push(`rename ${oldName} -> ${finalName}: ${err.message}`);
    }
  }
  return count;
}

class NameRegistry {
  used = new Map;
  claim(name, scope2) {
    const scopes = this.used.get(name);
    if (scopes)
      scopes.push(scope2);
    else
      this.used.set(name, [scope2]);
  }
  overlaps(name, scope2) {
    const scopes = this.used.get(name);
    if (!scopes)
      return false;
    return scopes.some((prior) => related(prior, scope2));
  }
}
function related(a, b2) {
  for (let s = a;s; s = s.parent)
    if (s === b2)
      return true;
  for (let s = b2;s; s = s.parent)
    if (s === a)
      return true;
  return false;
}
function deconflict(unit, binding, proposed, registry2) {
  const useSites = [...binding.referencePaths, ...binding.constantViolations];
  const conflicts = (name) => unit.scope.hasBinding(name) || unit.scope.hasGlobal(name) || unit.scope.hasReference(name) || useSites.some((site) => site.scope.hasBinding(name)) || registry2.overlaps(name, unit.scope);
  if (!conflicts(proposed))
    return proposed;
  for (let n = 2;n < 1000; n++) {
    const candidate = `${proposed}${n}`;
    if (!conflicts(candidate))
      return candidate;
  }
  return `${proposed}_${unit.hash}`;
}
