// src/cli.ts
var USAGE = `astcomp -- JavaScript deobfuscation with a correctness oracle

  astcomp <input.js> [options]

Options
  -o, --out <file>      write output here (default: stdout)
      --rename          run stage 2, the model-driven renaming pass
      --provider <p>    anthropic | heuristic          (default: anthropic)
      --model <id>      naming model                   (default: claude-sonnet-5)
      --concurrency <n> in-flight naming requests      (default: 8)
      --verify          differentially execute input vs output and compare
      --no-exec         never execute input-derived code (see Safety below)
      --report          print pass statistics to stderr
      --max-rounds <n>  pipeline fixpoint cap          (default: 12)
  -h, --help
  -v, --version

Stages
  1  deterministic AST passes -- string arrays, control flow, aliases, dead code
  2  scope-accurate renaming, gated on alpha-equivalence with the input
  3  verification -- --verify runs both programs and compares observable behaviour

Safety
  astcomp EXECUTES ITS INPUT by default. decode-string-array runs the decoder;
  --verify runs both complete programs. node:vm is not a security boundary.
  For untrusted samples run the whole process inside a container:
    docker run --rm --network none --memory 512m --read-only \\
      -v "$PWD/sample.js:/in/sample.js:ro" astcomp /in/sample.js
  --no-exec disables input execution and leaves string arrays encoded.
`;
function parseArgs(argv) {
  const opts = {
    input: "",
    rename: false,
    provider: "anthropic",
    concurrency: 8,
    verify: false,
    report: false,
    maxRounds: 12,
    allowExec: true
  };
  const invalidValue = (flag, value) => {
    console.error(`invalid value for ${flag}: ${value}`);
  };
  for (let i = 0;i < argv.length; i++) {
    const arg = argv[i];
    const next = () => {
      const value = argv[i + 1];
      if (value === undefined || value.startsWith("-")) {
        console.error(`missing value for ${arg}`);
        return null;
      }
      i++;
      return value;
    };
    switch (arg) {
      case "-h":
      case "--help":
        console.log(USAGE);
        process.exit(0);
      case "-v":
      case "--version":
        console.log(package_default.version);
        process.exit(0);
      case "-o":
      case "--out": {
        const value = next();
        if (value === null)
          return null;
        opts.out = value;
        break;
      }
      case "--rename":
        opts.rename = true;
        break;
      case "--provider": {
        const value = next();
        if (value === null)
          return null;
        if (value !== "anthropic" && value !== "heuristic") {
          invalidValue(arg, value);
          return null;
        }
        opts.provider = value;
        break;
      }
      case "--model": {
        const value = next();
        if (value === null)
          return null;
        opts.model = value;
        break;
      }
      case "--concurrency": {
        const value = next();
        if (value === null)
          return null;
        const concurrency = Number(value);
        if (!Number.isSafeInteger(concurrency) || concurrency < 1) {
          invalidValue(arg, value);
          return null;
        }
        opts.concurrency = concurrency;
        break;
      }
      case "--verify":
        opts.verify = true;
        break;
      case "--no-exec":
        opts.allowExec = false;
        break;
      case "--report":
        opts.report = true;
        break;
      case "--max-rounds": {
        const value = next();
        if (value === null)
          return null;
        const maxRounds = Number(value);
        if (!Number.isSafeInteger(maxRounds) || maxRounds < 1) {
          invalidValue(arg, value);
          return null;
        }
        opts.maxRounds = maxRounds;
        break;
      }
      default:
        if (arg.startsWith("-")) {
          console.error(`unknown flag: ${arg}`);
          return null;
        }
        if (opts.input) {
          console.error(`unexpected argument: ${arg}`);
          return null;
        }
        opts.input = arg;
    }
  }
  if (!opts.input)
    return null;
  return opts;
}
function providerFor(opts) {
  if (opts.provider === "heuristic")
    return heuristicProvider();
  return anthropicProvider({ model: opts.model, concurrency: opts.concurrency });
}
async function main() {
  const opts = parseArgs(process.argv.slice(2));
  if (!opts) {
    console.log(USAGE);
    process.exit(process.argv.length > 2 ? 1 : 0);
  }
  if (!opts.allowExec && opts.verify) {
    console.error(`error: --no-exec and --verify conflict -- verification works by executing both programs.
` + "       Drop one. To verify a hostile sample, keep --verify and run astcomp inside a container.");
    process.exit(1);
  }
  const source = readFileSync(opts.input, "utf8");
  const ast = parse3(source, opts.input);
  const pipeline2 = runPipeline(ast, {
    maxRounds: opts.maxRounds,
    allowExec: opts.allowExec
  });
  let renameSummary = "";
  if (opts.rename) {
    const report = await renameAst(ast, {
      provider: providerFor(opts),
      concurrency: opts.concurrency,
      onProgress: (done, total) => {
        if (opts.report)
          process.stderr.write(`\rnaming ${done}/${total}`);
      }
    });
    if (opts.report)
      process.stderr.write("\r\x1B[K");
    if (!report.astIdentical) {
      console.error(`error: renaming changed the AST (${report.astDivergence}); rolled back`);
      process.exitCode = 2;
    }
    renameSummary = `  renamed ${report.renamed} bindings across ${report.units} scopes ` + `(${report.cacheHits} cache hits, ${report.skipped} skipped)
` + `  ast identical modulo names: ${report.astIdentical ? "yes" : "NO"}
`;
    for (const failure of report.failures.slice(0, 5)) {
      renameSummary += `  ! ${failure}
`;
    }
  }
  const output = print(ast);
  let verdict = "";
  if (opts.verify) {
    const result = differential(source, output);
    verdict = result.equal ? `  behaviour: identical
` : `  behaviour: DIVERGED -- ${result.divergence}
`;
    if (!result.equal)
      process.exitCode = 3;
  }
  if (opts.out)
    writeFileSync(opts.out, output);
  else
    process.stdout.write(output);
  if (opts.report) {
    const rows = summarize(pipeline2).filter((r) => r.edits > 0);
    const width = Math.max(...rows.map((r) => r.name.length), 12);
    process.stderr.write(`
${opts.input}: ${source.length} -> ${output.length} bytes
` + `  ${pipeline2.rounds} rounds, ${pipeline2.totalEdits} edits, ${pipeline2.ms.toFixed(0)}ms
` + rows.map((r) => `  ${r.name.padEnd(width)}  ${String(r.edits).padStart(6)} edits  ${r.ms.toFixed(0)}ms`).join(`
`) + `
` + renameSummary + verdict + pipeline2.warnings.map((w) => `  ! ${w}`).join(`
`) + (pipeline2.warnings.length ? `
` : ""));
  }
}
main().catch((err) => {
  console.error(`astcomp: ${err.message}`);
  process.exit(1);
});
